import{_ as t,o as a,c as r,a4 as o}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Guest calculation production activation","description":"","frontmatter":{},"headers":[],"relativePath":"operations/guest-calculation-production-activation.md","filePath":"operations/guest-calculation-production-activation.md","lastUpdated":1788414836000}'),i={name:"operations/guest-calculation-production-activation.md"};function d(n,e,s,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="guest-calculation-production-activation" tabindex="-1">Guest calculation production activation <a class="header-anchor" href="#guest-calculation-production-activation" aria-label="Permalink to &quot;Guest calculation production activation&quot;">​</a></h1><p>Status: <strong>assessment complete; activation readiness incomplete</strong> Assessment timestamp: <code>2026-09-02T23:54:32+05:30</code> (<code>Asia/Kolkata</code>) Release refresh: <code>2026-09-03</code> (<code>Asia/Kolkata</code>) Panchangam production baseline: <code>eec464e871afdce9268716233fed2eecc91ae17a</code> Epic: <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/234" target="_blank" rel="noreferrer">#234</a></p><p>This is the operator runbook for activating guest birth-profile calculation and Muhurtam election-chart screening. It records sequence and evidence; it is not authorization to merge, add credentials, deploy, relicense, or enable a public flag.</p><p>Refresh this record immediately before any Preview, merge, deployment, or activation approval. Reconfirm branch heads, CI/security check URLs, exact Vercel deployment IDs, environment-name inventories, public probes, and restore refs; the values below are a dated assessment, not perpetual release evidence.</p><h2 id="current-state" tabindex="-1">Current state <a class="header-anchor" href="#current-state" aria-label="Permalink to &quot;Current state&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>State</th></tr></thead><tbody><tr><td>Panchangam profile/Muhurtam UI</td><td>Live with both remote client flags off</td></tr><tr><td>Astro guest routes</td><td><a href="https://github.com/socraticsurge/astro-unified-core/pull/161" target="_blank" rel="noreferrer">PR #161</a> is green at <code>e7fb3fe6</code>; Preview is Ready; routes remain absent from Production</td></tr><tr><td>DashaFlow authenticated contracts</td><td><a href="https://github.com/socraticsurge/dashaflow-sidecar/pull/1" target="_blank" rel="noreferrer">PR #1</a> is green at <code>97eece13</code>; Preview is Ready; contracts remain unreleased</td></tr><tr><td>Panchangam activation-readiness work</td><td><a href="https://github.com/socraticsurge/telugu-calendar-utilities/pull/451" target="_blank" rel="noreferrer">PR #451</a> is open at <code>3bcc0da</code>; branch publication does not deploy GitHub Pages</td></tr><tr><td>Licensing</td><td>Technical inventory <code>dd90f800</code> completed; legal/rights-holder decision remains blocked by #231, #444, #445, and #449</td></tr><tr><td>Production geocoder/shared controls</td><td>Fixed adapters, shared cache, privacy controls, guest budgets, and gated authenticated migration exist at <code>e7fb3fe6</code>; provider/Redis terms, credentials, Preview certification, and owner approval remain blocked by #233 and its children</td></tr><tr><td>Authenticated three-service Preview</td><td><strong>Blocked:</strong> no exact pair-bound hosted Preview path exists yet</td></tr></tbody></table><h2 id="hard-gates" tabindex="-1">Hard gates <a class="header-anchor" href="#hard-gates" aria-label="Permalink to &quot;Hard gates&quot;">​</a></h2><p>All boxes must be supported by links to evidence.</p><ul><li>[ ] #231 records the approved Swiss Ephemeris <strong>and PySwissEph wrapper</strong> posture.</li><li>[ ] #444 audits existing PyPI and live-service exposure.</li><li>[ ] #445 implements and verifies the selected licensing posture.</li><li>[ ] #449 records wrapper rights or completes and verifies an approved replacement.</li><li>[ ] #443&#39;s DashaFlow producer invariants pass against the TCU consumers.</li><li>[ ] #233 records the provider, retention, cache, attribution, and abuse posture.</li><li>[ ] #446 implements and verifies the owner-approved geocoder and shared, fail-closed guest abuse controls. Candidate code is not certification.</li><li>[ ] #447 migrates and regression-tests the authenticated profile geocoder so guest activation does not leave a second ungoverned provider path.</li><li>[ ] An exact, owner-approved, pair-bound hosted Preview mechanism is implemented for all three services and their protected deployments.</li><li>[ ] Logs, analytics, and application-controlled server/shared cache contain no profile name, birth payload, natal chart, raw place-search text, raw IP, provider key, or bearer token. Provider transit of the submitted city/town query is separately disclosed and governed by approved terms.</li><li>[ ] Browser requests contain no profile name or cookies. Calculation responses may contain the documented narrow natal- or election-chart results, but must not echo birth inputs, raw IPs, provider credentials, bearer credentials, or raw upstream diagnostics.</li><li>[ ] Place-search responses carry only allowlisted structured provider/data attribution links, and the Panchangam UI visibly renders those links beside returned results at desktop and mobile widths.</li><li>[ ] #448 records exact deployment/check IDs, probes, privacy evidence, screenshots, and rollback rehearsal <strong>after</strong> #443, #445, #446, #447, and #449 are complete.</li><li>[ ] Owner approvals are recorded independently for Preview configuration, each merge, each Production deployment/configuration change, and each public client-flag activation.</li></ul><h2 id="version-record" tabindex="-1">Version record <a class="header-anchor" href="#version-record" aria-label="Permalink to &quot;Version record&quot;">​</a></h2><p>Fill this table without secret values.</p><p>Do not reuse one value for production, candidate, or rollback. Record immutable deployment IDs rather than mutable aliases.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Current Production commit</th><th>Candidate commit</th><th>Restore ref</th><th>Preview deployment ID</th><th>Production deployment ID</th><th>CI/security evidence</th></tr></thead><tbody><tr><td>Panchangam</td><td><code>eec464e871afdce9268716233fed2eecc91ae17a</code></td><td><code>3bcc0da839b34b28a8000a2e993d06f7a0d70473</code></td><td><code>archive/guest-activation-readiness-2026-09-03-3bcc0da</code>; Production baseline <code>archive/release-2026-09-01-master-profile-muhurtam-eec464e</code></td><td>blocked; no exact pair-bound hosted Preview</td><td><code>gh-pages</code> tip <code>d456da46a29998ec8b49d9b35d63443fec3b6ca7</code>, tree <code>248cb16b391e9a36e99cf11116c9316dfcf6e93b</code></td><td>local: 406 frontend and 1,464 Python tests, both TypeScript configurations, production/docs build, 62 computation routes, 11 Mermaid diagrams, and 3 landing artifacts passed; PR #451 checks are green at <code>3bcc0da</code>, and this refresh commit requires its own checks</td></tr><tr><td>Astro</td><td><code>519d686486a91d694de652f4a393174a52c346fc</code></td><td><code>e7fb3fe6e8e05f47f04aaa1b19ce9447d92ad315</code></td><td><code>archive/astro-managed-geocoder-controls-2026-09-03-e7fb3fe</code>; deployment <code>dpl_F6yWeNZ2Mx9fzdjwMnan19cM9HdY</code></td><td><code>dpl_CA16AEiMt52qsywcVBnjK857ZcDd</code> (Ready, protected)</td><td><code>dpl_F6yWeNZ2Mx9fzdjwMnan19cM9HdY</code></td><td>GitHub tests and Vercel Preview green; local 683 tests, TypeScript, lint (one inherited warning), palette, routes, production build, and independent no-P0/P1/P2 review passed</td></tr><tr><td>DashaFlow</td><td><code>2c98ee8ef0c4a261686c507d9732f7834bc6b4f8</code></td><td><code>97eece13f524cc70bf995ae27620068a7d6aad44</code></td><td><code>archive/dashaflow-contract-remediation-2026-09-03-97eece1</code>; deployment <code>dpl_8Aoh11sqvj3yHPESkXRYRj8L4VHA</code></td><td><code>dpl_HetXHkbuH4BdKn8vnmGfpWanx6bX</code> (Ready, protected)</td><td><code>dpl_8Aoh11sqvj3yHPESkXRYRj8L4VHA</code></td><td>GitHub tests and both Vercel Preview checks green; local 103 tests and compileall passed</td></tr></tbody></table><h2 id="environment-names-and-implementation-state" tabindex="-1">Environment names and implementation state <a class="header-anchor" href="#environment-names-and-implementation-state" aria-label="Permalink to &quot;Environment names and implementation state&quot;">​</a></h2><p>These are names only. Never record values here, in issues, or in browser code.</p><table tabindex="0"><thead><tr><th>Owner</th><th>Current implemented name</th><th>Current boundary</th></tr></thead><tbody><tr><td>Panchangam build</td><td><code>VITE_BIRTH_PROFILE_API_ENABLED</code></td><td>exact <code>true</code>; exercise independently</td></tr><tr><td>Panchangam build</td><td><code>VITE_ELECTION_CHART_API_ENABLED</code></td><td>exact <code>true</code>; exercise independently</td></tr><tr><td>Panchangam build</td><td><code>VITE_BIRTH_PROFILE_API_BASE</code></td><td>implemented, but a deployed build accepts only the canonical Production Astro base; it cannot target a hosted Preview today</td></tr><tr><td>Panchangam build</td><td><code>VITE_ELECTION_CHART_API_BASE</code></td><td>same deployed-host restriction; it cannot target a hosted Preview today</td></tr><tr><td>Astro</td><td><code>GUEST_BIRTH_PROFILE_ENABLED</code></td><td>exact <code>true</code>; deployed/ambiguous runtimes otherwise fail closed</td></tr><tr><td>Astro</td><td><code>GUEST_ELECTION_CHART_ENABLED</code></td><td>exact <code>true</code>; deployed/ambiguous runtimes otherwise fail closed</td></tr><tr><td>Astro</td><td><code>DASHAFLOW_SIDECAR_URL</code></td><td>approved HTTPS service only when deployed</td></tr><tr><td>Astro</td><td><code>DASHAFLOW_SIDECAR_TOKEN</code></td><td>server-only credential sent by Astro</td></tr><tr><td>DashaFlow</td><td><code>DASHAFLOW_API_TOKEN</code></td><td>server-only verifier; its value must match Astro&#39;s differently named token</td></tr><tr><td>Astro</td><td><code>GEOCODER_PROVIDER</code>, <code>GEOCODER_API_KEY</code></td><td>implemented fixed-adapter pair; one owner-approved provider and server-only key are required when deployed; no provider/key is selected or configured</td></tr><tr><td>Astro</td><td><code>AUTH_PROFILE_MANAGED_GEOCODER_ENABLED</code></td><td>separate exact-<code>true</code> migration gate; omission/false preserves the existing signed-in profile path while guest work is reviewed; activation requires its own Preview and owner approval</td></tr><tr><td>Astro</td><td><code>UPSTASH_REDIS_REST_URL</code>, <code>UPSTASH_REDIS_REST_TOKEN</code></td><td>preferred complete pair for shared guest limits, activated authenticated per-user/fleet limits, and 24-hour normalized geocoder cache</td></tr><tr><td>Astro</td><td><code>KV_REST_API_URL</code>, <code>KV_REST_API_TOKEN</code></td><td>complete compatibility pair only; never combine a URL/token across namespaces</td></tr><tr><td>Astro runtime</td><td><code>VERCEL_ENV</code>, <code>VERCEL</code>, <code>NODE_ENV</code></td><td>implementation classifies only consistent explicit local or deployed markers; missing, unknown, self-hosted-production, or contradictory markers fail closed</td></tr></tbody></table><p>The named provider and shared-cache contracts are implemented in local Astro candidate <code>e7fb3fe6</code>, but provider selection, terms, quota/billing posture, credentials, and hosted certification remain unapproved. Existing signed-in profiles remain isolated from that migration unless its separate flag is exact <code>true</code>. No current environment variable makes the TCU/Astro/DashaFlow hosted Preview chain safe or reachable. Any such variables must be added only as part of the reviewed pair-bound mechanism.</p><h3 id="place-search-retention-and-quota-contract" tabindex="-1">Place-search retention and quota contract <a class="header-anchor" href="#place-search-retention-and-quota-contract" aria-label="Permalink to &quot;Place-search retention and quota contract&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Boundary</th><th>Permitted data</th><th>Retention / verification gate</th></tr></thead><tbody><tr><td>Panchangam browser request</td><td>Trimmed city/town query only; no profile name, cookie, birth date/time, or chart</td><td>Transient request state; browser network evidence required</td></tr><tr><td>Astro process state</td><td>Ephemeral HMAC client pseudonym; SHA-256 request key; normalized provider rows while pending</td><td>Per-process limiter window or bounded process lifetime; raw query/IP inspection required</td></tr><tr><td>Redis REST</td><td>HMAC cache/rate-limit key; at most five normalized provider rows</td><td>Geocoder rows expire after 24 hours; rate limits after one minute; GET/SET response and value are bounded</td></tr><tr><td>Managed geocoder</td><td>Submitted city/town query, provider credential, and Astro&#39;s server egress metadata</td><td>Provider-controlled; select the exact plan/region only after terms, privacy, attribution, and deletion/retention review</td></tr><tr><td>Sentry / application analytics</td><td>No request bodies, raw place query, provider URL query/key, birth payload, or chart</td><td>Verify configuration and inspect Preview events before activation</td></tr></tbody></table><p>The current geocoder fleet ceiling is 60 calls per minute, shared by guest place search and the separately activated authenticated migration. The managed authenticated path also applies a 10-call-per-user minute limit. In the worst case of unique cache misses, the shared fleet ceiling permits 86,400 provider calls in 24 hours. Provider approval must either select a plan that safely covers this bound or lower/add a daily fleet budget; the minute limiter alone must not be mistaken for a purchased-plan quota.</p><h2 id="hosted-preview-blocker-and-future-sequence" tabindex="-1">Hosted Preview blocker and future sequence <a class="header-anchor" href="#hosted-preview-blocker-and-future-sequence" aria-label="Permalink to &quot;Hosted Preview blocker and future sequence&quot;">​</a></h2><p><strong>Stop: #448 is not executable with the current clients and deployments.</strong> A deployed Panchangam build accepts only the canonical Production Astro API, Astro CORS accepts only the Production Panchangam origin (plus loopback), and the server-to-server clients do not carry an approved Vercel deployment- protection credential. A protected Vercel Preview therefore cannot certify the real browser-to-Astro-to-DashaFlow chain. Do not point a Preview browser at Production, add a wildcard <code>*.vercel.app</code> origin, disable Preview protection, or create an automation-bypass token as an undocumented side effect.</p><p>Before the sequence below becomes executable, implement and approve a mechanism that binds one immutable Panchangam Preview deployment to one immutable Astro Preview deployment and one immutable DashaFlow Preview deployment. It must allowlist only the exact browser origin, restrict each client to the exact next service, support the approved protection/authentication path without exposing a credential to browser JavaScript, and have negative cross-pair tests.</p><p>After that prerequisite and all hard gates are complete:</p><ol><li>Record the three candidate commits, immutable Preview deployment IDs, exact pair bindings, check URLs, and named restore refs.</li><li>Verify DashaFlow locally, including coherent 1-chart and 24-chart contracts, then deploy only its Preview.</li><li>Configure the distinct Astro/DashaFlow token names with one approved Preview-only value; verify missing/bad credentials and sanitized errors.</li><li>Configure the owner-approved geocoder and shared controls at Astro. Keep both guest flags and <code>AUTH_PROFILE_MANAGED_GEOCODER_ENABLED</code> off while dependencies and destination restrictions are probed.</li><li>Enable the Astro birth route only, then build the bound Panchangam Preview with only the birth flag. Verify place search, calculation, save, reload, profile detail, and Daily Horoscope reuse.</li><li>Keep election-chart flags off during a defined birth-only observation window; record duration, traffic/errors, provider/limit behavior, and privacy inspection results.</li><li>Disable birth or preserve its verified state, then exercise election alone: verify 1/24-chart batches, rating evidence, unknown/failure behavior, and Muhurtam reuse.</li><li>Only after both isolated observations, test both capabilities together.</li><li>Separately test signed-in profile create/edit while the authenticated migration flag is off, then on in Preview. Verify the per-user/shared fleet limits and restore it off before completing the guest-only evidence.</li><li>Attach browser network evidence, screenshots, application/platform/provider log checks, cache-key inspection, and negative cross-pair tests to #448.</li><li>Rehearse rollback at every layer before requesting any merge approval.</li></ol><h2 id="failure-matrix" tabindex="-1">Failure matrix <a class="header-anchor" href="#failure-matrix" aria-label="Permalink to &quot;Failure matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Failure</th><th>Expected behavior</th></tr></thead><tbody><tr><td>Client flag absent/malformed</td><td>No remote call; manual profile entry or conservative unscreened Muhurtam result</td></tr><tr><td>Astro route flag off</td><td>Fixed 503; no geocoder/sidecar call</td></tr><tr><td>Shared limiter missing/unavailable in Preview/Production</td><td>Fixed 503; no expensive calculation/provider call</td></tr><tr><td>Geocoder missing/unavailable</td><td>Place search 503; no fallback to public Nominatim</td></tr><tr><td>Authenticated migration flag absent/false</td><td>Existing signed-in Nominatim path remains available; managed adapter and Redis are not consulted</td></tr><tr><td>Authenticated migration exact <code>true</code>, dependency/limit unavailable</td><td>Signed-in place-changing operation fails closed; no public-Nominatim fallback and no DB mutation</td></tr><tr><td>Sidecar token missing/bad</td><td>Fixed gateway error; no upstream diagnostic or token in response</td></tr><tr><td>Sidecar timeout/transient error</td><td>Up to two bounded attempts within the browser deadline, with one retry only for 502/503/504, then a fixed unavailable result</td></tr><tr><td>Malformed/inconsistent chart</td><td>502/invalid response; never save or score as verified</td></tr><tr><td>Unsupported or ambiguous civil time</td><td>422; offer manual entry</td></tr></tbody></table><h2 id="merge-and-production-sequence" tabindex="-1">Merge and Production sequence <a class="header-anchor" href="#merge-and-production-sequence" aria-label="Permalink to &quot;Merge and Production sequence&quot;">​</a></h2><p>Production starts only after every hard gate above is complete: parent decisions #231 and #233, audit #444, implementation gates #443, #445, #446, #447, and #449, then exact-chain certification #448. The owner must still approve merges. Preview approval, merge approval, Production deployment/configuration approval, and feature activation approval are separate decisions.</p><ol><li>With explicit merge approval, merge DashaFlow first, then Astro. Do not deploy either merely because its PR merged.</li><li>With separate deployment approval, deploy the exact recorded DashaFlow commit with both new consumers still inactive; smoke the authenticated v1 routes.</li><li>Deploy the exact recorded Astro commit with both guest route flags and the authenticated migration flag off; verify fixed disabled guest responses and unchanged signed-in profile create/edit before dependency probes.</li><li>With a distinct activation approval, enable Astro birth only and publish the Panchangam build with only <code>VITE_BIRTH_PROFILE_API_ENABLED=true</code>.</li><li>Smoke and observe birth profiles for the recorded window. Keep both election flags off throughout that observation period.</li><li>After evidence review and a separate election activation approval, enable the Astro election route and publish the election-enabled client build.</li><li>Record immutable Production deployment IDs, timestamps, probes, privacy/log checks, feature-flag states, and restore refs after every step.</li></ol><p>Publishing the Panchangam build may require a workflow/configuration change. <code>.github/workflows/</code> is frozen in this repository and its current path filters do not make a docs-only commit a production activation mechanism. Any workflow change requires explicit owner approval and its own reviewed branch.</p><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Record distinct current-Production, candidate, and restore identifiers before each mutation. A mutable branch name, alias, or “previous deployment” label is not sufficient.</p><ul><li><strong>Feature kill:</strong> first set the matching Astro server flag false and redeploy, then publish a Panchangam build with the corresponding <code>VITE_*</code> flag absent or false. During token rollback, keep both routes off until old/new credentials have completed an approved overlap or coordinated cutover.</li><li><strong>Panchangam code:</strong> restore the recorded Production commit. The known pre-activation restore branch is <code>archive/release-2026-09-01-master-profile-muhurtam-eec464e</code> at baseline <code>eec464e</code>; verify the ref again at release time.</li><li><strong>Astro/DashaFlow:</strong> restore the separately recorded immutable deployment IDs and commits. Do not assume a Vercel alias still points to the reviewed build.</li><li><strong>Provider/control failure:</strong> keep guest server flags and the authenticated migration flag off. Guest search and an activated authenticated migration do not fall back to public Nominatim; the explicitly disabled authenticated migration preserves only the pre-existing signed-in path.</li><li><strong>Browser data:</strong> preserve the profile schema and stored records; disabling remote calculation must not make existing profiles unreadable.</li><li><strong>GitHub Pages:</strong> preserve and compare the complete published <code>gh-pages</code> tip and tree, not only <code>index.html</code>. The rollback manifest must include <code>CNAME</code>, all current feeds and per-city Lagna JSON, the Gochara snapshot, the retained Rasi Phalalu tree, built assets, and the site shell. Follow <a href="./gh-pages-retention">GitHub Pages retention and rollback</a>; do not repeat a partial orphan deployment that drops layered artifacts.</li></ul><h2 id="decision-links" tabindex="-1">Decision links <a class="header-anchor" href="#decision-links" aria-label="Permalink to &quot;Decision links&quot;">​</a></h2><ul><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/231" target="_blank" rel="noreferrer">Licensing gate #231</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/444" target="_blank" rel="noreferrer">Existing-distribution audit #444</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/445" target="_blank" rel="noreferrer">License-posture implementation #445</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/449" target="_blank" rel="noreferrer">PySwissEph rights or replacement #449</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/233" target="_blank" rel="noreferrer">Geocoder gate #233</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/443" target="_blank" rel="noreferrer">Producer invariants #443</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/446" target="_blank" rel="noreferrer">Managed geocoder/shared controls #446</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/447" target="_blank" rel="noreferrer">Authenticated geocoder migration #447</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/448" target="_blank" rel="noreferrer">Preview certification #448</a></li></ul>',36)])])}const m=t(i,[["render",d]]);export{p as __pageData,m as default};
